public class OpenApiEdgeCasesTest {}
/**************TEST SETUP BEGIN*************/
@BeforeEach
void setup() throws IOException{
        port = freePort();
        currentCtxId = "ctx-edge-" + CTX_COUNTER.incrementAndGet() + "-" + UUID.randomUUID();
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
void getOpenApiJson_repeatedRequests_returnConsistentSpec() throws Exception{
        startServer(new SwaggerConfiguration()
                .resourceClasses(Collections.singleton(HelloResource.class.getName())), false);

        String first = given(spec)
                .when().get("/openapi.json")
                .then().statusCode(200).extract().body().asString();

        String second = given(spec)
                .when().get("/openapi.json")
                .then().statusCode(200).extract().body().asString();

        String third = given(spec)
                .when().get("/openapi.json")
                .then().statusCode(200).extract().body().asString();

        assertTrue(first.equals(second), "Repeated requests must return identical spec (caching)");
        assertTrue(second.equals(third), "Repeated requests must return identical spec (caching)");
    }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private void startServer(SwaggerConfiguration swaggerConfig, boolean useAcceptHeader) throws Exception{
        ConfigurableOpenApiResource resource = new ConfigurableOpenApiResource(currentCtxId);
        resource.setOpenApiConfiguration(swaggerConfig);

        ResourceConfig appConfig = new ResourceConfig();
        appConfig.register(resource);
        appConfig.register(HelloResource.class);

        server = GrizzlyHttpServerFactory.createHttpServer(
                URI.create("http://localhost:" + port + "/"), appConfig);

        spec = RestAssured.given().baseUri("http://localhost").port(port);
    }
/**************TEST HELPER METHOD END*************/
/**************TEST TEARDOWN BEGIN*************/
@AfterEach
void teardown(){
        if (server != null) {
            server.shutdownNow();
            server = null;
        }
    }
/**************TEST TEARDOWN END*************/


